scene = uavScenario(UpdateRate=200, StopTime=2);
addMesh(scene, "Polygon", {[-100 0; 100 0; 100 100; -100 100], [-5 0]});
traj = waypointTrajectory(Waypoints=[0 -20 -5; 20 -20 -5; 20 0 -5]);
uavPlatform("UAV", scene, Trajectory=traj);
setup(scene);
while advance(scene)
    updateSensors(scene);
    show3D(scene); drawnow limitrate
end

plat = uavPlatform("UAV1", scene, InitialPosition=[0 0 -10]);
updateMesh(plat, "quadrotor", {1.2}, [1 0 0], eye(4));
motion = [1 0 -10, zeros(1,6), 1 0 0 0, zeros(1,3)];   % [pos vel acc quat(wxyz) angvel]
move(plat, motion);

lidarModel = uavLidarPointCloudGenerator(MaxRange=50, AzimuthResolution=0.5);
lidar = uavSensor("Lidar", plat, lidarModel, MountingLocation=[0 0 -0.4]);
setup(scene); advance(scene); updateSensors(scene);
[ok, t, pc] = read(lidar);

model = multirotor;
s = state(model); s(3) = 100;           % altitude
u = control(model); u.Thrust = 1;
e = environment(model);
[t, y] = ode45(@(~, x) derivative(model, x, u, e), [0 10], s);
plot(t, y(:,3))

model = fixedwing;
s = state(model); s(4) = 5;              % initial airspeed
u = control(model); u.Height = 100; u.AirSpeed = 12; u.RollAngle = 0.2;
e = environment(model);
[t, y] = ode45(@(~, x) derivative(model, x, u, e), [0 50], s);

